from __future__ import annotations

import threading

_ID = "main"
_value = 0
_lock = threading.Lock()


def _state():
    return {"id": _ID, "value": _value}


def _get():
    with _lock:
        return 200, _state()


def _increment():
    global _value
    with _lock:
        _value += 1
        return 200, _state()


def _decrement():
    global _value
    with _lock:
        _value -= 1
        return 200, _state()


def _reset():
    global _value
    with _lock:
        _value = 0
        return 200, _state()


_ROUTES = {
    "/counter": {"GET": _get},
    "/counter/increment": {"POST": _increment},
    "/counter/decrement": {"POST": _decrement},
    "/counter/reset": {"POST": _reset},
}


def handle(method: str, path: str, body: bytes) -> tuple[int, dict]:
    try:
        p = path or "/"
        if len(p) > 1:
            p = p.rstrip("/") or "/"
        route = _ROUTES.get(p)
        if route is None:
            return 404, {"error": "找不到此路徑"}
        fn = route.get(str(method).upper())
        if fn is None:
            return 405, {"error": "不支援此請求方法"}
        return fn()
    except Exception:
        return 500, {"error": "伺服器內部錯誤"}

