(function () {
  var countEl = document.getElementById('count');
  var errorEl = document.getElementById('error');
  var buttons = [
    document.getElementById('btn-dec'),
    document.getElementById('btn-reset'),
    document.getElementById('btn-inc')
  ];

  function showError(msg) {
    errorEl.textContent = msg;
    errorEl.hidden = false;
  }

  function clearError() {
    errorEl.textContent = '';
    errorEl.hidden = true;
  }

  function setBusy(busy) {
    buttons.forEach(function (b) { b.disabled = busy; });
  }

  async function call(doFetch) {
    var res;
    try {
      res = await doFetch();
    } catch (e) {
      throw new Error('無法連線到伺服器，請稍後再試。');
    }
    var text = '';
    try { text = await res.text(); } catch (e) { text = ''; }
    var data = null;
    try { data = JSON.parse(text); } catch (e) { data = null; }
    if (!res.ok) {
      if (data && typeof data.error === 'string' && data.error) {
        throw new Error(data.error);
      }
      throw new Error('請求失敗（HTTP ' + res.status + '）');
    }
    if (!data || typeof data.value !== 'number') {
      throw new Error('伺服器回應的格式不正確。');
    }
    return data;
  }

  async function run(doFetch) {
    setBusy(true);
    try {
      var data = await call(doFetch);
      countEl.textContent = String(data.value);
      clearError();
    } catch (e) {
      showError(e.message);
    } finally {
      setBusy(false);
    }
  }

  document.getElementById('btn-inc').addEventListener('click', function () {
    run(function () {
      return fetch('api/counter/increment', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    });
  });
  document.getElementById('btn-dec').addEventListener('click', function () {
    run(function () {
      return fetch('api/counter/decrement', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    });
  });
  document.getElementById('btn-reset').addEventListener('click', function () {
    run(function () {
      return fetch('api/counter/reset', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    });
  });

  run(function () {
    return fetch('api/counter', { method: 'GET' });
  });
})();

